create table public.incidents(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.jobs on delete restrict,assignment_id uuid references public.assignments on delete restrict,provider_company_id uuid references public.provider_companies on delete restrict,crew_id uuid references public.crews on delete restrict,completion_submission_id uuid references public.completion_submissions on delete restrict,reporter_id uuid not null references public.profiles on delete restrict,reporter_role public.app_role not null,category text not null check(category in ('customer_injury','crew_injury','third_party_injury','property_damage','item_damage','missing_item','unsafe_location','threatening_behavior','vehicle_incident','access_problem','prohibited_hazardous_material','illegal_disposal_concern','provider_conduct','customer_conduct','service_abandonment','other')),reported_severity text not null check(reported_severity in ('low','moderate','high','critical')),internal_severity text check(internal_severity in ('low','moderate','high','critical')),status text not null default 'reported' check(status in ('draft','reported','triage','awaiting_customer_information','awaiting_provider_information','awaiting_crew_information','under_investigation','resolution_proposed','resolved','closed','reopened','void')),occurred_at timestamptz not null,reported_at timestamptz not null default now(),description text not null check(length(description) between 20 and 10000),immediate_safety_action text,injury_indicator boolean not null default false,emergency_services_indicator boolean not null default false,damage_indicator boolean not null default false,missing_item_indicator boolean not null default false,hazard_indicator boolean not null default false,customer_visible_summary text,internal_notes text,assigned_reviewer uuid references public.profiles on delete set null,resolution_summary text,resolved_at timestamptz,related_support_request uuid references public.support_requests on delete set null,request_id uuid not null,unique(reporter_id,request_id));
create table public.incident_updates(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.incidents on delete restrict,actor_id uuid not null references public.profiles on delete restrict,actor_role public.app_role not null,from_status text,to_status text,customer_visible boolean not null default false,provider_visible boolean not null default false,message text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.claims(id uuid primary key default gen_random_uuid(),incident_id uuid not null references public.incidents on delete restrict,job_id uuid not null references public.jobs on delete restrict,provider_company_id uuid references public.provider_companies on delete restrict,claimant_id uuid not null references public.profiles on delete restrict,status text not null default 'open' check(status in ('open','information_gathering','provider_response_requested','customer_response_requested','under_review','resolution_proposed','accepted','declined','withdrawn','closed','reopened')),loss_category text not null,customer_description text,provider_response text,claimed_amount_cents bigint check(claimed_amount_cents is null or claimed_amount_cents>=0),currency text not null default 'usd' check(currency='usd'),approved_amount_placeholder_cents bigint check(approved_amount_placeholder_cents is null or approved_amount_placeholder_cents>=0),resolution_type text,resolution_notes text,decision_actor uuid references public.profiles on delete restrict,decision_at timestamptz,created_by uuid not null references public.profiles on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.in_app_notifications(id uuid primary key default gen_random_uuid(),recipient_id uuid not null references public.profiles on delete cascade,event_key text not null,entity_type text not null,entity_id uuid,route text not null check(route like '/%'),safe_preview text not null check(length(safe_preview)<=240),read_at timestamptz,idempotency_key uuid not null,created_at timestamptz not null default now(),unique(recipient_id,event_key,idempotency_key));
create table public.closure_policies(id uuid primary key default gen_random_uuid(),service public.job_service not null unique,customer_response_hours int not null default 72 check(customer_response_hours between 0 and 720),active boolean not null default true,created_at timestamptz not null default now());insert into public.closure_policies(service) values('move'),('remove');
do $$declare t text;begin foreach t in array array['incidents','incident_updates','claims','in_app_notifications','closure_policies'] loop execute format('alter table public.%I enable row level security',t);end loop;end $$;
create trigger immutable_incident_updates before update or delete on public.incident_updates for each row execute function public.prevent_event_mutation();create trigger set_claims_updated before update on public.claims for each row execute function public.set_updated_at();
create index incidents_job_status_idx on public.incidents(job_id,status);create index incidents_review_idx on public.incidents(status,reported_at);create index claims_incident_status_idx on public.claims(incident_id,status);create index notifications_recipient_idx on public.in_app_notifications(recipient_id,read_at,created_at desc);

create or replace function public.can_access_incident(p_incident uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.incidents i where i.id=p_incident and (public.has_any_role(array['dispatcher','compliance_admin','super_admin']::public.app_role[]) or public.owns_job(i.job_id) or public.crew_has_assigned_job(i.job_id) or (i.provider_company_id is not null and public.can_manage_provider(i.provider_company_id)))) $$;
revoke all on function public.can_access_incident(uuid) from public;grant execute on function public.can_access_incident(uuid) to authenticated;
create policy "authorized users read incidents" on public.incidents for select to authenticated using(public.can_access_incident(id));create policy "authorized users read incident updates" on public.incident_updates for select to authenticated using(public.can_access_incident(incident_id) and (public.has_any_role(array['dispatcher','compliance_admin','super_admin']::public.app_role[]) or (public.owns_job((select job_id from public.incidents where id=incident_id)) and customer_visible) or provider_visible));
create policy "authorized users read claims" on public.claims for select to authenticated using(public.has_any_role(array['dispatcher','compliance_admin','super_admin']::public.app_role[]) or claimant_id=auth.uid() or (provider_company_id is not null and public.can_manage_provider(provider_company_id)));
create policy "users read own notifications" on public.in_app_notifications for select to authenticated using(recipient_id=auth.uid());create policy "operations read closure policies" on public.closure_policies for select to authenticated using(public.has_any_role(array['dispatcher','super_admin']::public.app_role[]));

create or replace function public.create_incident(p_job uuid,p_category text,p_severity text,p_occurred_at timestamptz,p_description text,p_safety_action text,p_flags jsonb,p_customer_summary text,p_request_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_role public.app_role;v_a public.assignments%rowtype;v_id uuid;begin select role into v_role from public.profiles where id=auth.uid();if v_role is null then raise exception 'authentication required';end if;select * into v_a from public.assignments where job_id=p_job and status not in ('canceled','reassignment_required') order by created_at desc limit 1;if not(public.owns_job(p_job) or public.crew_has_assigned_job(p_job) or (v_a.provider_company_id is not null and public.can_manage_provider(v_a.provider_company_id)) or v_role in ('dispatcher','compliance_admin','super_admin')) then raise exception 'job not found';end if;if p_category not in ('customer_injury','crew_injury','third_party_injury','property_damage','item_damage','missing_item','unsafe_location','threatening_behavior','vehicle_incident','access_problem','prohibited_hazardous_material','illegal_disposal_concern','provider_conduct','customer_conduct','service_abandonment','other') or p_severity not in ('low','moderate','high','critical') or length(trim(coalesce(p_description,''))) not between 20 and 10000 or p_occurred_at>now()+interval '5 minutes' then raise exception 'invalid incident';end if;if v_role='customer' and (select count(*) from public.incidents where reporter_id=auth.uid() and reported_at>now()-interval '1 hour')>=5 then raise exception 'too many incident reports';end if;insert into public.incidents(job_id,assignment_id,provider_company_id,crew_id,reporter_id,reporter_role,category,reported_severity,status,occurred_at,description,immediate_safety_action,injury_indicator,emergency_services_indicator,damage_indicator,missing_item_indicator,hazard_indicator,customer_visible_summary,request_id) values(p_job,v_a.id,v_a.provider_company_id,v_a.crew_id,auth.uid(),v_role,p_category,p_severity,'reported',p_occurred_at,trim(p_description),nullif(trim(coalesce(p_safety_action,'')),''),coalesce((p_flags->>'injury')::boolean,false),coalesce((p_flags->>'emergency_services')::boolean,false),coalesce((p_flags->>'damage')::boolean,false),coalesce((p_flags->>'missing_item')::boolean,false),coalesce((p_flags->>'hazard')::boolean,false),nullif(trim(coalesce(p_customer_summary,'')),''),p_request_id) returning id into v_id;if p_severity in ('high','critical') then update public.jobs set status='incident_hold' where id=p_job and status not in ('closed','cancelled');insert into public.job_status_events(job_id,status,actor_id,note,metadata) values(p_job,'incident_hold',auth.uid(),'MUBER is reviewing a reported safety or service concern.',jsonb_build_object('customer_visible',true));end if;insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata,request_id) values(auth.uid(),'incident.reported','incident',v_id,jsonb_build_object('job_id',p_job,'category',p_category,'reported_severity',p_severity,'fault_determined',false),p_request_id);return v_id;end $$;
revoke all on function public.create_incident(uuid,text,text,timestamptz,text,text,jsonb,text,uuid) from public;grant execute on function public.create_incident(uuid,text,text,timestamptz,text,text,jsonb,text,uuid) to authenticated;

create or replace function public.review_incident(p_incident uuid,p_action text,p_severity text,p_message text,p_internal_notes text,p_request_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v_i public.incidents%rowtype;v_role public.app_role;v_to text;begin select role into v_role from public.profiles where id=auth.uid();if v_role not in ('dispatcher','compliance_admin','super_admin') then raise exception 'forbidden';end if;select * into v_i from public.incidents where id=p_incident for update;if not found then raise exception 'incident not found';end if;v_to:=case when p_action='triage' and v_i.status in ('reported','reopened') then 'triage' when p_action='request_customer' and v_i.status not in ('resolved','closed','void') then 'awaiting_customer_information' when p_action='request_provider' and v_i.status not in ('resolved','closed','void') then 'awaiting_provider_information' when p_action='request_crew' and v_i.status not in ('resolved','closed','void') then 'awaiting_crew_information' when p_action='investigate' and v_i.status not in ('resolved','closed','void') then 'under_investigation' when p_action='propose_resolution' and v_i.status='under_investigation' then 'resolution_proposed' when p_action='resolve' and v_i.status in ('under_investigation','resolution_proposed') then 'resolved' when p_action='reopen' and v_i.status in ('resolved','closed') then 'reopened' else null end;if v_to is null or length(trim(coalesce(p_message,'')))<10 then raise exception 'invalid incident action';end if;if p_severity is not null and p_severity not in ('low','moderate','high','critical') then raise exception 'invalid severity';end if;update public.incidents set status=v_to,internal_severity=coalesce(p_severity,internal_severity),assigned_reviewer=auth.uid(),internal_notes=coalesce(nullif(trim(p_internal_notes),''),internal_notes),resolution_summary=case when v_to='resolved' then trim(p_message) else resolution_summary end,resolved_at=case when v_to='resolved' then now() else resolved_at end where id=p_incident;insert into public.incident_updates(incident_id,actor_id,actor_role,from_status,to_status,customer_visible,provider_visible,message) values(p_incident,auth.uid(),v_role,v_i.status,v_to,p_action in ('request_customer','propose_resolution','resolve'),p_action in ('request_provider','request_crew','propose_resolution','resolve'),trim(p_message));insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata,request_id) values(auth.uid(),'incident.'||p_action,'incident',p_incident,jsonb_build_object('from_status',v_i.status,'to_status',v_to,'severity',p_severity,'fault_determined',false),p_request_id);end $$;
revoke all on function public.review_incident(uuid,text,text,text,text,uuid) from public;grant execute on function public.review_incident(uuid,text,text,text,text,uuid) to authenticated;

create or replace function public.create_claim_from_incident(p_incident uuid,p_loss_category text,p_claimed_cents bigint,p_description text,p_request_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_i public.incidents%rowtype;v_id uuid;begin if not public.has_any_role(array['compliance_admin','super_admin']::public.app_role[]) then raise exception 'compliance authorization required';end if;select * into v_i from public.incidents where id=p_incident;if not found or v_i.status='void' then raise exception 'incident not found';end if;if length(trim(coalesce(p_loss_category,'')))<3 or p_claimed_cents<0 then raise exception 'invalid claim';end if;insert into public.claims(incident_id,job_id,provider_company_id,claimant_id,loss_category,customer_description,claimed_amount_cents,created_by) values(p_incident,v_i.job_id,v_i.provider_company_id,v_i.reporter_id,trim(p_loss_category),nullif(trim(coalesce(p_description,'')),''),p_claimed_cents,auth.uid()) returning id into v_id;insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata,request_id) values(auth.uid(),'claim.opened','claim',v_id,jsonb_build_object('incident_id',p_incident,'claimed_amount_cents',p_claimed_cents,'financial_ledger_created',false,'liability_admitted',false),p_request_id);return v_id;end $$;
revoke all on function public.create_claim_from_incident(uuid,text,bigint,text,uuid) from public;grant execute on function public.create_claim_from_incident(uuid,text,bigint,text,uuid) to authenticated;

create or replace function public.job_closure_readiness(p_job uuid) returns jsonb language plpgsql stable security definer set search_path=public as $$ declare v_job public.jobs%rowtype;v_blockers text[]:='{}';v_completion public.completion_submissions%rowtype;v_hours int;begin if not public.has_any_role(array['dispatcher','super_admin']::public.app_role[]) then raise exception 'forbidden';end if;select * into v_job from public.jobs where id=p_job;if not found then raise exception 'job not found';end if;if v_job.status<>'completed' then v_blockers:=array_append(v_blockers,'Job is not completed');end if;select * into v_completion from public.completion_submissions where job_id=p_job order by version desc limit 1;if not found or v_completion.status<>'approved' then v_blockers:=array_append(v_blockers,'Completion review is not approved');end if;select customer_response_hours into v_hours from public.closure_policies where service=v_job.service and active;if v_completion.customer_confirmation_status='problem_reported' then v_blockers:=array_append(v_blockers,'Customer reported a completion problem');elsif v_completion.customer_confirmation_status<>'confirmed' and v_completion.reviewed_at+make_interval(hours=>coalesce(v_hours,72))>now() then v_blockers:=array_append(v_blockers,'Customer response window remains open');end if;if exists(select 1 from public.incidents where job_id=p_job and status not in ('resolved','closed','void') and coalesce(internal_severity,reported_severity) in ('high','critical')) then v_blockers:=array_append(v_blockers,'High or critical incident remains open');end if;if exists(select 1 from public.claims where job_id=p_job and status not in ('declined','withdrawn','closed')) then v_blockers:=array_append(v_blockers,'Claim remains open');end if;if exists(select 1 from public.completion_submissions where job_id=p_job and status in ('more_information_requested','returned_to_provider')) then v_blockers:=array_append(v_blockers,'Completion information remains requested');end if;return jsonb_build_object('eligible',cardinality(v_blockers)=0,'blockers',v_blockers,'payment_settled',false);end $$;
revoke all on function public.job_closure_readiness(uuid) from public;grant execute on function public.job_closure_readiness(uuid) to authenticated;

create or replace function public.close_job(p_job uuid,p_reason text,p_request_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare v_ready jsonb;begin if not public.has_any_role(array['dispatcher','super_admin']::public.app_role[]) then raise exception 'forbidden';end if;if length(trim(coalesce(p_reason,'')))<10 then raise exception 'closure reason required';end if;if exists(select 1 from public.audit_events where actor_id=auth.uid() and action='job.closed' and request_id=p_request_id) then return jsonb_build_object('closed',true,'idempotent',true);end if;perform 1 from public.jobs where id=p_job for update;v_ready:=public.job_closure_readiness(p_job);if not(v_ready->>'eligible')::boolean then return v_ready;end if;update public.jobs set status='closed' where id=p_job;insert into public.job_status_events(job_id,status,actor_id,note,metadata) values(p_job,'closed',auth.uid(),'This job is closed. Support remains available.',jsonb_build_object('customer_visible',true,'payment_settled',false));insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata,request_id) values(auth.uid(),'job.closed','job',p_job,jsonb_build_object('reason',trim(p_reason),'checklist',v_ready,'payment_settled',false),p_request_id);return jsonb_build_object('closed',true,'blockers','[]'::jsonb);end $$;
revoke all on function public.close_job(uuid,text,uuid) from public;grant execute on function public.close_job(uuid,text,uuid) to authenticated;

create or replace function public.reopen_job(p_job uuid,p_reason text,p_request_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not public.has_any_role(array['super_admin']::public.app_role[]) or length(trim(coalesce(p_reason,'')))<10 then raise exception 'super administrator and reason required';end if;update public.jobs set status='completed' where id=p_job and status='closed';if not found then raise exception 'job is not closed';end if;insert into public.job_status_events(job_id,status,actor_id,note,metadata) values(p_job,'completed',auth.uid(),'This job was reopened for operational review.',jsonb_build_object('customer_visible',true,'payment_settled',false));insert into public.audit_events(actor_id,action,entity_type,entity_id,metadata,request_id) values(auth.uid(),'job.reopened','job',p_job,jsonb_build_object('reason',trim(p_reason),'payment_settled',false),p_request_id);end $$;
revoke all on function public.reopen_job(uuid,text,uuid) from public;grant execute on function public.reopen_job(uuid,text,uuid) to authenticated;

create or replace function public.mark_notification_read(p_notification uuid) returns void language sql security definer set search_path=public as $$ update public.in_app_notifications set read_at=coalesce(read_at,now()) where id=p_notification and recipient_id=auth.uid() $$;revoke all on function public.mark_notification_read(uuid) from public;grant execute on function public.mark_notification_read(uuid) to authenticated;

-- Preserve the reporter's original allegation while allowing controlled review fields.
create or replace function public.protect_incident_report() returns trigger language plpgsql as $$
begin
  if old.job_id is distinct from new.job_id
    or old.assignment_id is distinct from new.assignment_id
    or old.provider_company_id is distinct from new.provider_company_id
    or old.crew_id is distinct from new.crew_id
    or old.completion_submission_id is distinct from new.completion_submission_id
    or old.reporter_id is distinct from new.reporter_id
    or old.reporter_role is distinct from new.reporter_role
    or old.category is distinct from new.category
    or old.reported_severity is distinct from new.reported_severity
    or old.occurred_at is distinct from new.occurred_at
    or old.reported_at is distinct from new.reported_at
    or old.description is distinct from new.description
    or old.immediate_safety_action is distinct from new.immediate_safety_action
    or old.injury_indicator is distinct from new.injury_indicator
    or old.emergency_services_indicator is distinct from new.emergency_services_indicator
    or old.damage_indicator is distinct from new.damage_indicator
    or old.missing_item_indicator is distinct from new.missing_item_indicator
    or old.hazard_indicator is distinct from new.hazard_indicator
    or old.request_id is distinct from new.request_id then
    raise exception 'original incident report is immutable';
  end if;
  return new;
end $$;
create trigger protect_incident_report before update on public.incidents for each row execute function public.protect_incident_report();
create trigger prevent_incident_delete before delete on public.incidents for each row execute function public.prevent_event_mutation();

create or replace function public.incident_update_visible(p_incident uuid,p_customer boolean,p_provider boolean) returns boolean language sql stable security definer set search_path=public as $$
  select exists(
    select 1 from public.incidents i where i.id=p_incident and (
      public.has_any_role(array['dispatcher','compliance_admin','super_admin']::public.app_role[])
      or (p_customer and public.owns_job(i.job_id))
      or (p_provider and (public.crew_has_assigned_job(i.job_id) or (i.provider_company_id is not null and public.can_manage_provider(i.provider_company_id))))
    )
  )
$$;
revoke all on function public.incident_update_visible(uuid,boolean,boolean) from public;
grant execute on function public.incident_update_visible(uuid,boolean,boolean) to authenticated;
drop policy "authorized users read incident updates" on public.incident_updates;
create policy "authorized users read incident updates" on public.incident_updates for select to authenticated using(public.incident_update_visible(incident_id,customer_visible,provider_visible));

-- Table writes remain RPC-only. Authenticated users receive only policy-filtered reads.
grant select on public.incidents,public.incident_updates,public.claims,public.in_app_notifications,public.closure_policies to authenticated;
revoke insert,update,delete on public.incidents,public.incident_updates,public.claims,public.in_app_notifications,public.closure_policies from authenticated;
